<script setup>
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import UiIcon from '../components/UiIcon.vue'
import RepairsPanel from './RepairsPanel.vue'
import StatusTag from '../components/StatusTag.vue'
import {navigation} from '../data.js'
import OverviewSummary from './OverviewSummary.vue'
import {createPlatformClient,relationRows,formatNumber,statusLabel,orderPresentation,scopeRecords,scopeDeviceCatalog} from './platformClient.js'
import './connected.css'
import ConnectedEditor from './ConnectedEditor.vue'
import DeviceLayout from './DeviceLayout.vue'
import SocketQr from '../components/SocketQr.vue'
import OperationsPanel from '../components/OperationsPanel.vue'
import DashboardStationMap from '../components/DashboardStationMap.vue'
import {currentAbnormalDeviceIds,mapConnectedSource} from '../domain/operations.js'
const user=ref(null),username=ref(''),password=ref(''),loginError=ref(''),loginBusy=ref(false),page=ref('dashboard'),collapsed=ref(false),error=ref(''),busy=ref(false),loadedAt=ref(''),keyword=ref(''),dialog=ref(null),actionBusy=ref(false),message=ref('')
const data=reactive({stations:[],devices:[],sockets:[],orders:[],reports:[],reportsLoaded:false}),users=ref({rows:[],total:0,page:1,totalPages:1}),usersBusy=ref(false),rates=ref([]),rateStation=ref(''),ratesBusy=ref(false),ratesError=ref(''),audit=ref({rows:[],page:1,totalPages:1}),auditBusy=ref(false),auditError=ref('')
const repairsPanel=ref(null),editor=ref(null),socketBusy=ref(false),scope=ref({})
const scopedData=computed(()=>scopeDeviceCatalog(data,{...scope.value,abnormalDeviceIds:currentAbnormalDeviceIds(source.value)}))
const canWrite=computed(()=>user.value?.role==='ADMIN'),source=computed(()=>mapConnectedSource(data))
async function saved(){editor.value=null;message.value='服务端数据已保存。';await refresh();if(page.value==='rates')await loadRates()}
async function changeSocket(socket,status){if(!canWrite.value||socketBusy.value)return;socketBusy.value=true;error.value='';try{await client.setSocketStatus(socket.id,status);dialog.value=null;socketBusy.value=false;await refresh()}catch(e){if(!e.stale)error.value=e.message+'；请刷新核对结果。'}finally{socketBusy.value=false}}
async function removeRate(row){if(!canWrite.value||actionBusy.value||!window.confirm('确认删除此费率时段？未覆盖全天时用户将不能启动新订单。'))return;actionBusy.value=true;try{await client.deleteRate(row.id);await loadRates()}catch(e){if(!e.stale)ratesError.value=e.message}finally{actionBusy.value=false}}
function openDevice(id){const record=data.devices.find(d=>String(d.id)===String(id));if(record)dialog.value={type:'device',record};else error.value='设备记录已变化，请刷新后重试。'}
function openOrder(id){const record=data.orders.find(o=>String(o.id)===String(id));if(record)showOrder(record);else error.value='订单记录已变化，请刷新后重试。'}
let revision=0,rateRevision=0,timer
const client=createPlatformClient({onExpired:()=>logout('登录已过期，请重新登录业务后端。')})
function clear(){revision++;rateRevision++;Object.assign(data,{stations:[],devices:[],sockets:[],orders:[],reports:[],reportsLoaded:false});scope.value={};users.value={rows:[],total:0,page:1,totalPages:1};rates.value=[];audit.value={rows:[],page:1,totalPages:1};rateStation.value='';dialog.value=null;loadedAt.value='';error.value='';message.value='';editor.value=null;busy.value=false;usersBusy.value=false;ratesBusy.value=false;auditBusy.value=false;actionBusy.value=false;ratesError.value='';auditError.value=''}
function logout(text='已退出本页面的业务后端会话。'){client.logout();user.value=null;clear();loginError.value=text;clearInterval(timer)}
async function login(){loginBusy.value=true;loginError.value='';try{clear();user.value=await client.login(username.value.trim(),password.value);password.value='';page.value='dashboard';await refresh();timer=setInterval(()=>{if(!document.hidden&&!busy.value&&!actionBusy.value&&!dialog.value&&!editor.value&&user.value)refresh()},5000)}catch(e){if(!e.stale)loginError.value=e.message}finally{password.value='';loginBusy.value=false}}
function requirePage(value){if(!value||!Array.isArray(value.rows)||!Number.isFinite(Number(value.total)))throw Error('后端分页格式不正确。');return value}
async function refresh(){if(!user.value||busy.value||usersBusy.value||actionBusy.value||socketBusy.value)return;const v=revision;busy.value=true;error.value='';try{const [stations,devices,sockets,orders,userPage]=await Promise.all([client.stations(),client.devices(),client.sockets(),client.orders(),client.users(users.value.page)]);if(v!==revision)return;requirePage(userPage);Object.assign(data,{stations,devices,sockets,orders});users.value=userPage;if(user.value.features?.repairs){try{const reports=await client.repairs();if(v!==revision)return;data.reports=reports;data.reportsLoaded=true}catch(e){if(v!==revision)return;data.reportsLoaded=false;if(!e.stale)message.value='报修待办未能读取，请在故障报修中重试。'}}loadedAt.value=new Date().toLocaleTimeString('zh-CN',{hour12:false})}catch(e){if(v===revision&&!e.stale)error.value=(loadedAt.value?'刷新失败，以下为上次成功读取的数据。':'未能读取服务端数据。')+e.message}finally{if(v===revision)busy.value=false}}
async function loadUsers(target){if(usersBusy.value||busy.value||actionBusy.value)return;const v=revision;usersBusy.value=true;error.value='';try{const result=requirePage(await client.users(target));if(v===revision)users.value=result}catch(e){if(v===revision&&!e.stale)error.value=e.message}finally{if(v===revision)usersBusy.value=false}}
async function toggleUser(){if(actionBusy.value)return;const target=dialog.value?.record;if(!target)return;const v=revision;actionBusy.value=true;error.value='';try{await client.setUserEnabled(target.id,!target.enabled);const result=requirePage(await client.users(users.value.page));if(v!==revision)return;users.value=result;message.value='服务端账号状态已更新。';dialog.value=null}catch(e){if(v===revision&&!e.stale)error.value=e.message+'；请刷新核对服务端结果。'}finally{if(v===revision)actionBusy.value=false}}
async function loadRates(){const v=++rateRevision,session=revision;if(!rateStation.value){rates.value=[];return}ratesBusy.value=true;ratesError.value='';rates.value=[];try{const result=await client.rates(rateStation.value);if(v===rateRevision&&session===revision)rates.value=result}catch(e){if(v===rateRevision&&session===revision&&!e.stale)ratesError.value=e.message}finally{if(v===rateRevision&&session===revision)ratesBusy.value=false}}
async function loadAudit(target=1){if(auditBusy.value)return;const v=revision;auditBusy.value=true;auditError.value='';try{const result=requirePage(await client.audit(target));if(v===revision)audit.value=result}catch(e){if(v===revision&&!e.stale)auditError.value=e.message}finally{if(v===revision)auditBusy.value=false}}
async function showOrder(record){const v=revision;dialog.value={type:'loading'};try{const result=await client.order(record.id);if(v===revision)dialog.value={type:'order',record:result}}catch(e){if(v===revision&&!e.stale){dialog.value=null;error.value=e.message}}}
function navigate(value){const target=typeof value==='string'?{page:value}:value;page.value=target.page;scope.value={...target};keyword.value='';dialog.value=null;message.value='';if(target.page==='rates'){rateStation.value=String(target.stationId||rateStation.value||data.stations[0]?.id||'');loadRates()}}
const title=computed(()=>navigation.find(n=>n.id===page.value)?.label||'运营概览'),relations=computed(()=>relationRows(data.stations,data.devices,data.sockets)),stationName=id=>data.stations.find(s=>s.id===id)?.name||`站点 #${id}`,socketName=id=>data.sockets.find(s=>s.id===id)?.code||`插座 #${id}`
const definitions={stations:{columns:[['name','站点名称'],['address','地址'],['position','坐标'],['deviceCount','设备数'],['socketCount','插座数'],['state','运营状态']]},devices:{columns:[['code','设备编号'],['name','设备名称'],['stationName','所属站点'],['socketCount','插座数量'],['state','通信状态']]},orders:{columns:[['orderNo','订单编号'],['owner','用户账号'],['stationName','站点'],['socketCode','插座编号'],['startTime','开始时间'],['energy','电量（kWh）'],['amount','费用（元）'],['state','订单状态'],['payment','支付状态']]},users:{columns:[['username','账号'],['displayName','名称'],['state','账号状态']]},rates:{columns:[['startTime','开始时间'],['endTime','结束时间'],['electric','电价（元/kWh）']]}}
const rows=computed(()=>{let result=[];if(page.value==='stations')result=relations.value.stations.map(s=>({...s,position:s.latitude==null||s.longitude==null?'未提供':`${s.latitude}, ${s.longitude} · ${s.coordinateType||'坐标系未提供'}`,state:statusLabel(s.status,'station')}));if(page.value==='devices')result=relations.value.devices.map(d=>({...d,state:statusLabel(d.status,'device')}));if(page.value==='orders')result=data.orders.map(o=>({...o,owner:o.ownerUsername||'未提供',stationName:stationName(o.stationId),socketCode:socketName(o.connectorId),energy:formatNumber(o.energyKwh,3),amount:formatNumber(o.totalAmount),state:statusLabel(o.status,'order'),payment:statusLabel(o.paymentStatus,'payment')}));if(page.value==='users')result=users.value.rows.map(u=>({...u,state:u.enabled?'启用':'停用'}));if(page.value==='rates')result=rates.value.map(r=>({...r,electric:formatNumber(r.electricityPrice),service:formatNumber(r.servicePrice)}));if(['devices','orders'].includes(page.value))result=scopeRecords(result,{...scope.value,abnormalDeviceIds:currentAbnormalDeviceIds(source.value)});if(page.value==='orders'&&scope.value.date)result=result.filter(r=>String(r.startTime).slice(0,10)===scope.value.date);if(page.value==='orders'&&scope.value.completedOnly)result=result.filter(r=>r.status==='COMPLETED');const q=keyword.value.trim().toLowerCase();return result.filter(r=>!q||Object.values(r).some(v=>String(v??'').toLowerCase().includes(q)))})
const displayPage=ref(1),pageSize=20,visible=computed(()=>page.value==='users'?rows.value:rows.value.slice((displayPage.value-1)*pageSize,displayPage.value*pageSize)),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/pageSize)))
watch(pages,value=>{if(displayPage.value>value)displayPage.value=value})
function changeKeyword(){displayPage.value=1}function nav(value){displayPage.value=1;navigate(value)}
const selectedSockets=computed(()=>dialog.value?.type==='device'?data.sockets.filter(s=>s.chargerId===dialog.value.record.id):[])
onBeforeUnmount(()=>{clearInterval(timer);client.logout()})
</script>
<template>
 <main v-if="!user" class="auth-shell connected-login"><div class="auth-brand"><span class="auth-logo">ϟ</span>电动自行车智慧充电管理系统</div><section class="login-card"><div class="login-accent"></div><header><h1>业务后端管理登录</h1><p>后端联调版 · 使用统一 Spring Boot 接口</p></header><p v-if="loginError" class="form-error" role="alert">{{loginError}}</p><form @submit.prevent="login"><label>业务后端账号<input v-model="username" required autocomplete="username" maxlength="64"/></label><label>密码<input v-model="password" type="password" required autocomplete="current-password" maxlength="72"/></label><button class="login-submit" :disabled="loginBusy">{{loginBusy?'正在连接…':'登 录'}}</button></form><div class="login-help">使用现有业务后端的 ADMIN / OPERATOR 账号。此账号与 5195 本机模拟版账号不同；不内置密码，刷新后需重新登录。<br/>管理员可维护配置；运营员可查询和处理本人负责的报修。</div></section></main>
 <div v-else class="platform connected-platform" :class="{'sidebar-collapsed':collapsed}">
  <aside class="sidebar"><a class="brand" href="#" @click.prevent="nav('dashboard')"><span class="auth-logo">ϟ</span><span class="brand-name">电动自行车<br/>智慧充电管理系统</span></a><nav class="navigation" aria-label="主导航"><div v-for="item in navigation" :key="item.id" class="nav-group"><button class="nav-item" :class="{active:page===item.id}" @click="nav(item.id)"><UiIcon :name="item.icon"/><span>{{item.label}}</span></button></div></nav></aside>
  <header class="topbar"><button class="icon-button fold-button" aria-label="切换导航" @click="collapsed=!collapsed"><UiIcon name="menu"/></button><div class="breadcrumbs">统一业务后端 / <strong>{{title}}</strong></div><div class="topbar-tools connected-tools"><span class="preview-mode-chip">后端联调版</span><button v-if="canWrite" class="text-button" @click="dialog={type:'audit'};loadAudit()">操作日志</button><span>{{user.displayName||user.username}}</span><button class="text-button" @click="logout()">退出</button></div></header>
  <main class="main-content"><p v-if="!canWrite" class="remote-message">运营员账号：基础配置只读，可记录告警并处理分派给本人的报修。</p><div class="tab-strip"><button class="active-tab">{{title}}</button><span class="tab-mode-note">{{loadedAt?'最近同步 '+loadedAt:'尚未读取数据'}}</span><button class="text-button remote-refresh" :disabled="busy||actionBusy" @click="page==='reports'?repairsPanel?.reload():refresh()">{{busy?'读取中…':'刷新服务端数据'}}</button></div>
   <p v-if="error" class="remote-error" role="alert">{{error}}</p><p v-if="message" class="remote-message" role="status">{{message}}</p>
   <section v-if="page==='dashboard'" class="management-page remote-overview"><header class="management-heading"><div><h1>服务端运营概览</h1><p>全部数字来自当前接口响应；设备与订单仍属于软件演示系统，不代表实物运行。</p></div></header><OverviewSummary :source="source" :loaded="!!loadedAt" @navigate="nav" @device="openDevice" @order="openOrder"/><DashboardStationMap v-if="loadedAt" :source="source" @navigate="nav"/><OperationsPanel :source="source" :client="client" :show-metrics="false" :account-key="user.username" @device="openDevice" @order="openOrder" @navigate="nav"/><div class="remote-readiness"><h2>已接通的业务</h2><p>站点与位置、设备与插座、历史订单及费用、普通用户分页查询和启停、分时费率、后端操作日志。</p><h2>当前后端边界</h2><p>按服务端实际设备和插座数量展示；可查看启动结果、订单账单和报修处理。电量采用软件/设备模拟；支付区分本地模拟与支付宝沙箱测试，不代表正式收款。</p><p>管理端与移动端使用同一个服务地址与数据库；读取到的订单结果以服务端为准。此模式不读取 5195 的浏览器模拟缓存。</p></div></section>
   <OperationsPanel v-else-if="page==='operations'" :source="source" :client="client" :account-key="user.username" @device="openDevice" @order="openOrder" @navigate="nav"/><RepairsPanel v-else-if="page==='reports'" ref="repairsPanel" :client="client" :enabled="user.features?.repairs===true" :admin="canWrite" :scope="scope" @clear-scope="scope={}"/>
   <section v-else class="management-page"><header class="management-heading"><div><h1>{{title}}</h1><p>{{page==='devices'?'按服务端排号分组；新增设备固定为每台 A/B 两个独立插座。':page==='users'?'仅管理普通用户；状态更新由服务端校验并记录日志。':page==='orders'?'订单状态与支付状态分别展示，金额不由前端重新计算。':page==='rates'?'完整展示所选站点的分时费率，不使用模拟单价。':'站点位置采用服务端坐标与坐标系，不推测缺失坐标。'}}</p></div></header>
    <div class="filter-bar"><button v-if="canWrite&&['stations','devices','rates'].includes(page)" class="soft-button active" @click="editor={type:page}">新增{{page==='stations'?'站点':page==='devices'?'一批设备':'费率时段'}}</button><input v-model="keyword" aria-label="筛选服务端列表" placeholder="筛选当前已加载数据" @input="changeKeyword"/><template v-if="page==='rates'"><select v-model="rateStation" aria-label="选择费率站点" @change="displayPage=1;loadRates()"><option value="">选择站点</option><option v-for="s in data.stations" :key="s.id" :value="String(s.id)">{{s.name}}</option></select><button class="outline-button" :disabled="ratesBusy||!rateStation" @click="loadRates">刷新费率</button></template></div><p v-if="ratesError&&page==='rates'" class="remote-error" role="alert">{{ratesError}}</p>
    <p v-if="scope.stationId||scope.abnormalOnly||scope.date" class="remote-message scope-indicator">当前范围：{{scope.stationId?stationName(scope.stationId):'全部站点'}} {{scope.abnormalOnly?'· 异常设备':''}} {{scope.date?'· 开始日期 '+scope.date:''}} <button class="text-button" @click="scope={};keyword='';displayPage=1">清除关联筛选</button></p><DeviceLayout v-if="page==='devices'" :data="scopedData" @open="openDevice"/><div class="management-table-wrap"><table class="management-table"><thead><tr><th>序号</th><th v-for="[key,label] in definitions[page].columns" :key="key">{{label}}</th><th v-if="['stations','devices','orders','users','rates'].includes(page)">操作</th></tr></thead><tbody><tr v-for="(row,i) in visible" :key="row.id"><td>{{(page==='users'?Number(users.page)-1:displayPage-1)*pageSize+i+1}}</td><td v-for="[key] in definitions[page].columns" :key="key"><StatusTag v-if="['state','payment'].includes(key)" :text="row[key]"/><span v-else>{{row[key]??'—'}}</span></td><td v-if="['stations','devices','orders','users','rates'].includes(page)"><button v-if="canWrite&&['stations','devices','rates'].includes(page)" class="table-link" @click="editor={type:page==='devices'?'device':page,record:row}">编辑</button><button v-if="canWrite&&page==='rates'" class="table-link" @click="removeRate(row)">删除</button><button v-if="page==='stations'" class="table-link" @click="dialog={type:'station',record:row}">关联业务</button><button v-if="page==='devices'" class="table-link" @click="dialog={type:'device',record:row}">查看插座</button><button v-if="page==='orders'" class="table-link" @click="showOrder(row)">详情</button><button v-if="canWrite&&page==='users'" class="table-link" :disabled="actionBusy||usersBusy||busy||row.role!=='USER'" @click="dialog={type:'user',record:row}">{{row.enabled?'停用':'启用'}}</button></td></tr><tr v-if="!visible.length"><td :colspan="definitions[page].columns.length+2" class="empty-table">{{busy||ratesBusy||usersBusy?'正在读取服务端…':error||ratesError?'读取未完成，请处理提示后重试':'暂无符合条件的服务端记录'}}</td></tr></tbody></table></div>
    <footer class="remote-pagination"><span>{{page==='users'?'当前服务端分页共 '+users.total+' 位普通用户；筛选仅针对本页':'筛选结果共 '+rows.length+' 条'}}</span><template v-if="page==='users'"><button class="outline-button" :disabled="usersBusy||busy||actionBusy||users.page<=1" @click="loadUsers(Number(users.page)-1)">上一页</button><span>{{users.page}} / {{Math.max(1,users.totalPages)}}</span><button class="outline-button" :disabled="usersBusy||busy||actionBusy||users.page>=users.totalPages" @click="loadUsers(Number(users.page)+1)">下一页</button></template><template v-else><button class="outline-button" :disabled="displayPage<=1" @click="displayPage--">上一页</button><span>{{displayPage}} / {{pages}}</span><button class="outline-button" :disabled="displayPage>=pages" @click="displayPage++">下一页</button></template></footer>
   </section>
  </main>
  <div v-if="editor" class="modal-shade"><section class="modal-card" role="dialog" aria-modal="true" aria-label="业务数据编辑"><header><h2>维护业务数据</h2></header><ConnectedEditor :key="editor.type+':'+(editor.record?.id||'new')" :client="client" :type="editor.type" :record="editor.record" :stations="data.stations" :station-id="rateStation" @done="saved" @cancel="editor=null"/></section></div>
  <div v-if="dialog" class="modal-shade" @click.self="!actionBusy&&(dialog=null)"><section class="modal-card" role="dialog" aria-modal="true" aria-label="服务端记录详情"><header><h2>{{dialog.type==='station'?'站点关联业务':dialog.type==='audit'?'服务端操作日志':dialog.type==='user'?'确认用户状态':dialog.type==='device'?'设备与插座':'服务端订单详情'}}</h2><button class="icon-button" aria-label="关闭弹窗" :disabled="actionBusy" @click="dialog=null"><UiIcon name="close"/></button></header><div class="remote-detail">
   <template v-if="dialog.type==='station'"><h3>{{dialog.record.name}}</h3><p>{{dialog.record.address}}</p><p>{{dialog.record.deviceCount}} 台设备 · {{dialog.record.socketCount}} 个插座</p><div class="station-business-links"><button v-for="target in [{page:'devices',label:'设备与插座'},{page:'orders',label:'关联订单'},{page:'reports',label:'报修记录'},{page:'rates',label:'分时电价'}]" :key="target.page" class="outline-button" @click="nav({page:target.page,stationId:dialog.record.id})">{{target.label}}</button></div></template><template v-if="dialog.type==='loading'"><p>正在读取订单详情…</p></template>
   <template v-if="dialog.type==='device'"><h3>{{dialog.record.code}}</h3><p>{{dialog.record.rowName||'未提供排号'}} · 服务端共 {{selectedSockets.length}} 个插座。</p><div class="socket-grid"><article v-for="socket in selectedSockets" :key="socket.id" class="socket-card"><strong>{{socket.name||socket.code}}</strong><p>{{socket.code}}</p><StatusTag :text="statusLabel(socket.status,'socket')"/><p>配置功率：{{socket.powerWatts==null?'未提供':socket.powerWatts+' W'}}</p><div v-if="canWrite" class="socket-actions"><button class="table-link" :disabled="socketBusy||socket.status!=='IDLE'" @click="editor={type:'socket',record:socket};dialog=null">修改配置功率</button><button v-for="[value,label] in [['IDLE','核验恢复'],['FAULT','设为故障'],['DISABLED','停用']]" :key="value" class="table-link" :disabled="socketBusy||socket.status==='CHARGING'||socket.status===value" @click="changeSocket(socket,value)">{{label}}</button></div><SocketQr :code="socket.code"/></article></div></template>
   <template v-if="dialog.type==='order'"><div class="order-state-line"><StatusTag :text="statusLabel(dialog.record.status,'order')"/><StatusTag :text="statusLabel(dialog.record.paymentStatus,'payment')"/></div><dl class="detail-grid"><dt>订单编号</dt><dd>{{dialog.record.orderNo}}</dd><dt>用户</dt><dd>{{dialog.record.ownerUsername||'未提供'}}</dd><dt>站点</dt><dd>{{dialog.record.stationNameSnapshot||stationName(dialog.record.stationId)}}</dd><dt>插座</dt><dd>{{dialog.record.socketCodeSnapshot||socketName(dialog.record.connectorId)}}</dd><dt>充电方案</dt><dd>{{orderPresentation(dialog.record).plan}}</dd><dt>计量来源</dt><dd>{{orderPresentation(dialog.record).meter}}</dd><dt>配置功率</dt><dd>{{dialog.record.powerWatts??'—'}} W</dd><dt>预计结束</dt><dd>{{dialog.record.scheduledEndTime||'历史订单未记录'}}</dd><dt>结束原因</dt><dd>{{orderPresentation(dialog.record).reason}}</dd><dt>开始时间</dt><dd>{{dialog.record.startTime||'未提供'}}</dd><dt>结束时间</dt><dd>{{dialog.record.endTime||'未提供'}}</dd><dt>电量</dt><dd>{{formatNumber(dialog.record.energyKwh,3)}} kWh</dd><dt>电费</dt><dd>{{formatNumber(dialog.record.electricityFee)}} 元</dd><template v-if="Number(dialog.record.serviceFee)>0"><dt>历史服务费</dt><dd>{{formatNumber(dialog.record.serviceFee)}} 元</dd></template><dt>合计</dt><dd>{{formatNumber(dialog.record.totalAmount)}} 元</dd></dl><p class="form-hint">配置功率为启动时保存的插座参数；定时任务由业务后端执行。全部取自服务端账单。历史账单以服务端结果为准，不使用当前站点费率重新计算。</p></template>
   <template v-if="dialog.type==='user'"><p>确认{{dialog.record.enabled?'停用':'启用'}}普通用户 {{dialog.record.username}}？</p><p>将调用服务端账号状态接口，结果以服务端校验为准。</p><p v-if="error" class="remote-error" role="alert">{{error}}</p><button class="soft-button active" :disabled="actionBusy" @click="toggleUser">{{actionBusy?'正在更新…':'确认更新状态'}}</button></template>
   <template v-if="dialog.type==='audit'"><p>以下来自业务后端审计表，不是浏览器模拟日志。</p><p v-if="auditError" class="remote-error" role="alert">{{auditError}}</p><div class="management-table-wrap"><table class="management-table"><thead><tr><th>账号</th><th>请求</th><th>状态码</th><th>时间</th></tr></thead><tbody><tr v-for="item in audit.rows" :key="item.id"><td>{{item.username}}</td><td>{{item.method}} {{item.path}}</td><td>{{item.statusCode}}</td><td>{{item.createdAt}}</td></tr><tr v-if="!audit.rows.length"><td colspan="4">{{auditBusy?'读取中…':'暂无日志'}}</td></tr></tbody></table></div><div class="remote-pagination"><button class="outline-button" :disabled="auditBusy||audit.page<=1" @click="loadAudit(audit.page-1)">上一页</button><span>{{audit.page}} / {{Math.max(1,audit.totalPages)}}</span><button class="outline-button" :disabled="auditBusy||audit.page>=audit.totalPages" @click="loadAudit(audit.page+1)">下一页</button><button class="text-button" :disabled="auditBusy" @click="loadAudit(audit.page)">刷新日志</button></div></template>
  </div><footer><button class="outline-button" :disabled="actionBusy" @click="dialog=null">关闭</button></footer></section></div>
 </div>
</template>
